import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    h = int(data[0])
    n = int(data[1])

    # Recursive idea:
    # At each subtree of height hh, Amr first tries one side depending on depth parity:
    # depth 0 -> L first, depth 1 -> R first, depth 2 -> L first, ...
    #
    # If the exit is in the first-tried side:
    #   he enters that child directly, costing 1 visited node (the child),
    #   then continue inside.
    #
    # If the exit is in the other side:
    #   he fully explores the first-tried subtree and comes back, which costs
    #   all nodes of that subtree plus the child itself and returns:
    #   2^(hh) - 1 visited nodes before being back at current node,
    #   then he enters the correct child (+1), and continues.
    #
    # More compactly:
    # subtree_nodes(height hh) = 2^(hh+1) - 1
    # one child subtree total nodes = 2^hh - 1
    # exploring wrong side completely and returning, excluding current node,
    # costs 2^hh
    #
    # We count visited nodes excluding the exit itself.

    def solve(hh, nn, prefer_left):
        if hh == 0:
            return 0  # current node is the exit leaf, excluded

        left_leaves = 1 << (hh - 1)

        if prefer_left:
            if nn <= left_leaves:
                # Exit is in preferred side
                return 1 + solve(hh - 1, nn, not prefer_left)
            else:
                # Explore left subtree completely, then go right
                return (1 << hh) + solve(hh - 1, nn - left_leaves, not prefer_left)
        else:
            if nn > left_leaves:
                # Exit is in preferred side (right)
                return 1 + solve(hh - 1, nn - left_leaves, not prefer_left)
            else:
                # Explore right subtree completely, then go left
                return (1 << hh) + solve(hh - 1, nn, not prefer_left)

    print(solve(h, n, True))

if __name__ == "__main__":
    main()
